cJSON * cJSON_CreateProductProduct(const struct ProductProduct * x) {
    cJSON * j = NULL;
    if (NULL != x) {
        if (NULL != (j = cJSON_CreateObject())) {
            cJSON_AddNumberToObject(j, "categoryid", x->categoryid);
            cJSON_AddItemToObject(j, "currency", cJSON_CreateCurrency(x->currency));
            cJSON_AddBoolToObject(j, "eco", x->eco);
            cJSON_AddBoolToObject(j, "fulldescription", x->fulldescription);
            cJSON_AddBoolToObject(j, "hasmetasearch", x->hasmetasearch);
            cJSON_AddNumberToObject(j, "id", x->id);
            if (NULL != x->links) {
                cJSON * j1 = cJSON_AddArrayToObject(j, "links");
                if (NULL != j1) {
                    struct LinkElement * x1 = list_get_head(x->links);
                    while (NULL != x1) {
                        cJSON_AddItemToArray(j1, cJSON_CreateLinkElement(x1));
                        x1 = list_get_next(x->links);
                    }
                }
            }
            cJSON_AddNumberToObject(j, "numoffers", x->numoffers);
            if (NULL != x->pricemax) {
                cJSON_AddStringToObject(j, "pricemax", x->pricemax);
            }
            else {
                cJSON_AddStringToObject(j, "pricemax", "");
            }
            if (NULL != x->pricemin) {
                cJSON_AddStringToObject(j, "pricemin", x->pricemin);
            }
            else {
                cJSON_AddStringToObject(j, "pricemin", "");
            }
            if (NULL != x->productname) {
                cJSON_AddStringToObject(j, "productname", x->productname);
            }
            else {
                cJSON_AddStringToObject(j, "productname", "");
            }
            cJSON_AddNumberToObject(j, "quantity", x->quantity);
            cJSON_AddItemToObject(j, "rating", cJSON_CreateRating(x->rating));
            cJSON_AddItemToObject(j, "specification", cJSON_CreateSpecification(x->specification));
            cJSON_AddItemToObject(j, "thumbnail", cJSON_CreateFormatsClass(x->thumbnail));
            cJSON_AddNumberToObject(j, "totalsellers", x->totalsellers);
        }
    }
    return j;
}

